demo.program:
// cFS layered architecture check (simulated model)
var layers=['mission-apps','cFE-core','OSAL','PSP','hardware'];
console.log('cFS stack ('+layers.length+' layers):');
for(var i=0;i<layers.length;i++){console.log(' '+(i+1)+'. '+layers[i]);}
console.log('portability: only PSP changes per board');

// ES application registry demo (simulated model)
var apps=['HK','SCH','TBL','EVS'];
var reg={};
for(var i=0;i<apps.length;i++){reg[apps[i]]={id:100+i,state:'RUNNING'};}
console.log('ES registered '+apps.length+' apps:');
for(var k in reg){console.log(' '+k+' id='+reg[k].id+' '+reg[k].state);}

// Software Bus publish/subscribe routing (simulated model)
var subs={'0x1806':['TBL','HK'],'0x1801':['SCH']};
var pkt={mid:'0x1806',len:128};
var dest=subs[pkt.mid]||[];
console.log('publish '+pkt.mid+' ('+pkt.len+'B) -> '+dest.join(','));
console.log('decoupled delivery to '+dest.length+' subscribers');

// EVS event filtering demo (simulated model)
var evts=[['HK',2,'hk nominal'],['SCH',4,'slot overrun'],['TBL',1,'tbl debug']];
var thresh=2, passed=0;
for(var i=0;i<evts.length;i++){if(evts[i][1]>=thresh){passed++;console.log('EVT '+evts[i][0]+' sev='+evts[i][1]+': '+evts[i][2]);}}
console.log(passed+'/'+evts.length+' events passed the filter');

// Table Services double-buffer demo (simulated model)
var tbl={active:{gain:1.5,limit:10},inactive:{gain:1.7,limit:10}};
function crc(o){var s=JSON.stringify(o),h=0;for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h;}
console.log('active crc='+crc(tbl.active)+' inactive crc='+crc(tbl.inactive));
tbl.active=JSON.parse(JSON.stringify(tbl.inactive));
console.log('activated: gain='+tbl.active.gain+' (no rebuild needed)');

// TIME MET-to-UTC conversion demo (simulated model)
var met=86400*400+12345, leap=37, epoch=946684800;
var utc=epoch+met-leap;
var d=new Date(utc*1000);
console.log('MET '+met+'s -> UTC '+d.toISOString());
console.log('leap-second offset applied: '+leap+'s');

// OSAL abstraction demo (simulated model)
var osal={impl:'linux',tasks:0};
function OS_TaskCreate(name){osal.tasks++;return 'task-'+name+'#'+osal.tasks;}
console.log('OSAL on '+osal.impl+': '+OS_TaskCreate('HK')+', '+OS_TaskCreate('SCH'));
console.log('same API on RTEMS/VxWorks — app code unchanged');

// PSP board-support check demo (simulated model)
var psp={board:'rad750-class',tick_hz:100,watchdog:true,drivers:['uart','spacewire','eeprom']};
console.log('PSP for '+psp.board+': tick='+psp.tick_hz+'Hz watchdog='+(psp.watchdog?'on':'off'));
console.log('drivers: '+psp.drivers.join(', ')+' — apps above are untouched');

// SCH slot schedule demo (simulated model)
var slots=[['HK','0x1806'],['TBL','0x1808'],['EVS','0x1805']];
for(var minor=0;minor<2;minor++){
  for(var i=0;i<slots.length;i++){console.log('minor '+minor+' slot '+i+': send '+slots[i][1]+' to '+slots[i][0]);}
}
console.log('SCH dispatched '+slots.length*2+' messages over 2 minor frames');

// CCSDS primary header pack/unpack (simulated model)
var apid=0x406, seq=42, len=64;
var hdr=((apid&0x7ff)<<0)|(0x18<<11);
console.log('APID 0x'+apid.toString(16)+' seq '+seq+' len '+len);
console.log('header word1=0x'+hdr.toString(16)+' -> APID recovered 0x'+((hdr&0x7ff)).toString(16));

// CMake target matrix demo (simulated model)
var targets=[['linux','native'],['rtems','gr712rc'],['vxworks','rad750']];
var ok=0;
for(var i=0;i<targets.length;i++){console.log('build '+targets[i][0]+'/'+targets[i][1]+' ... OK');ok++;}
console.log(ok+'/'+targets.length+' targets built from one tree');

// Mission reuse accounting demo (simulated model)
var missions=[['GPM',12],['MMS',16],['LADEE',9],['DART',11]];
var tot=0;
for(var i=0;i<missions.length;i++){tot+=missions[i][1];console.log(missions[i][0]+': '+missions[i][1]+' mission apps on shared core');}
console.log(tot+' mission apps total, one shared cFE core');

// Coverage gate demo (simulated model)
var mods=[['cFE-ES',94],['cFE-SB',91],['OSAL',88],['PSP',83]];
var gate=85, pass=0;
for(var i=0;i<mods.length;i++){var ok=mods[i][1]>=gate;if(ok)pass++;console.log(mods[i][0]+' '+mods[i][1]+'% '+(ok?'PASS':'FAIL'));}
console.log(pass+'/'+mods.length+' modules above the '+gate+'% gate');

// Portability matrix demo (simulated model)
var cfgs=[['linux','debug','non-RT'],['rtems','flight','hard-RT'],['vxworks','flight','hard-RT']];
for(var i=0;i<cfgs.length;i++){console.log(cfgs[i][0]+': '+cfgs[i][1]+' build, '+cfgs[i][2]);}
console.log('identical app source across '+cfgs.length+' configs');

// End-to-end cFS loop demo (simulated model)
var steps=['cmd uplink','SB route','app executes','HK gather','EVS log','telemetry downlink'];
var t=0;
for(var i=0;i<steps.length;i++){t+=12;console.log('t+'+t+'ms '+steps[i]);}
console.log('command-to-telemetry loop closed in '+t+'ms');
